package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;import java.math.BigInteger;
/** Addition/subtraction answers derived from the visible fractions, with existing input rules. */
public final class PublicFractionArithmetic {
 private PublicFractionArithmetic(){}
 public static boolean supports(String id){return Set.of("fracAddLike","fracSubLike","fracAdd","fracSub","fracWholeSub").contains(id);}
 public static int[] givens(Question q){if(q==null||q.prompt==null||!supports(q.skillId))return null;if(WholeFractionSubtraction.ID.equals(q.skillId))return WholeFractionSubtraction.read(q);Matcher m=Pattern.compile("\\((\\d{1,3})/(\\d{1,3})\\)\\s*([+−-])\\s*\\((\\d{1,3})/(\\d{1,3})\\)").matcher(q.prompt);if(!m.matches())return null;int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(2)),c=Integer.parseInt(m.group(4)),d=Integer.parseInt(m.group(5));boolean add=q.skillId.startsWith("fracAdd");if(b<2||b>12||d<2||d>12||a<1||a>=b||c<1||c>=d||add!=m.group(3).equals("+")||q.skillId.endsWith("Like")&&b!=d||!add&&a*d<c*b)return null;return new int[]{a,b,c,d};}
 static Checker.Result check(Question q,List<String> answers){int[] v=givens(q);if(v==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"문제 확인 필요");Rational left=Rational.of(v[0],v[1]),right=Rational.of(v[2],v[3]);return checkValue(q,answers,q.skillId.startsWith("fracAdd")?left.add(right):left.sub(right));}
 static Checker.Result checkValue(Question q,List<String> answers,Rational expected){if(answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");String input=Expression.normalize(answers.get(0).trim());if(input.isEmpty()||input.length()>120)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"답 입력 필요");if("fraction".equals(q.answerFormat)&&!input.contains("/"))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"분수로 입력 필요");if("decimal".equals(q.answerFormat)&&(!input.contains(".")||input.contains("/")))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"소수로 입력 필요");if(!input.matches("[+-]?\\d+(?:\\.\\d+)?(?:/[+-]?\\d+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"마지막 답은 수로 입력");try{if(!Expression.number(input).equals(expected))return new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");if(q.kind.equals("reduced")){if(input.contains("."))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"분수로 입력 필요");if(input.contains("/")){String[] parts=input.split("/");if(!new BigInteger(parts[0]).gcd(new BigInteger(parts[1])).equals(BigInteger.ONE))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"약분 필요");}}return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");}catch(RuntimeException ex){return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"수 입력 확인 필요");}}
 /** Identify a single unchanged numerator/denominator; otherwise mark the pair. */
 public static int errorPart(Question q,String raw){int[] v=givens(q);if(v==null||raw==null||raw.length()>120||FractionInput.invalidPart(raw)!=0)return 0;String[] pair=FractionInput.parts(raw);BigInteger n=new BigInteger(pair[0]),d=new BigInteger(pair[1]);Rational left=Rational.of(v[0],v[1]),right=Rational.of(v[2],v[3]),value=q.skillId.startsWith("fracAdd")?left.add(right):left.sub(right);if(n.multiply(value.d).equals(value.n.multiply(d)))return 0;int denominator=v[1]/BigInteger.valueOf(v[1]).gcd(BigInteger.valueOf(v[3])).intValue()*v[3];int numerator=q.skillId.startsWith("fracAdd")?v[0]*(denominator/v[1])+v[2]*(denominator/v[3]):v[0]*(denominator/v[1])-v[2]*(denominator/v[3]);if(d.equals(value.d)||d.equals(BigInteger.valueOf(denominator)))return 1;if(n.equals(value.n)||n.equals(BigInteger.valueOf(numerator)))return 2;return 0;}

}
